await story('A8-09-expiry-setup',async()=>{
 const e=await context(cases[0]);await signIn(e.p,'expiry');await e.p.locator('#quickFleetLabel').fill('Natural expiry control');const response=e.p.waitForResponse(r=>new URL(r.url()).pathname==='/hub/v1/quick-pairing'&&r.request().method()==='POST');await e.p.locator('[data-quick-pairing] form button[type=submit]').click();const offer=await(await response).json();receipt.expiryOffer={expiresAt:offer.expiresAt,started:Date.now()};const code=(await e.p.locator('[data-quick-pairing] .hub-fp-groups').first().innerText()).trim();
 const eh=join(scratch,'expiry-member');mkdirSync(eh,{mode:0o700});const ep=createHubMemberPairingApi({home:eh,enabled:()=>true,link:()=> 'offline',pollMs:250});extraPairings.push(ep);fx.fm.attachHubMemberPairing(ep);
 const l=await context(cases[0]);const issued=await(await fetch(fx.base+'/auth/issue-code',{method:'POST',headers:{'X-Agend-Token':fx.fm.webToken}})).json();await l.p.goto(fx.base+'/signin');await l.p.fill('#code',issued.code);await l.p.click('#go');await l.p.waitForURL(fx.base+'/ui');await l.p.goto(fx.base+'/settings/hub');await l.p.fill('#hubAddress',memberOrigin);await l.p.fill('#hubCode',code);await l.p.locator('#hub-connect form button[type=submit]').click();await apply(l.p,'.hub-local-confirm');await e.p.getByRole('button',{name:'They match',exact:true}).waitFor({timeout:20000});
 for(const c of matrix('full').filter(c=>c.device==='phone')){const o=await context(c);await signIn(o.p,'expiry');await o.p.getByRole('button',{name:c.lang==='en'?'They match':'指紋相符',exact:true}).waitFor();await o.p.getByRole('button',{name:c.lang==='en'?'They match':'指紋相符',exact:true}).scrollIntoViewIfNeeded();await shot(o.p,`A8-09-pending-details-${caseName(c)}`);await o.ctx.close();}
 await e.p.getByRole('button',{name:'They match',exact:true}).click();await shot(e.p,'A8-09-expiry-before-local-proof');globalThis.a8Expiry={e,l,ep};check('owner proof submitted while local proof intentionally withheld',ep.view().state==='pending');console.log('EXPIRY_DEADLINE',new Date(offer.expiresAt).toISOString());
});
await story('A8-11-settled-revoked-room',async()=>{const o=await context(cases[0]);await signIn(o.p,'asker',new URL(roomUrl).pathname+new URL(roomUrl).search);await o.p.locator('.hub-chat').waitFor();await o.p.getByText('This chat has closed: your permission ended, or the agent is no longer shared.',{exact:true}).waitFor();await shot(o.p,'A8-11-revoked-room-settled');check('settled revoked room explains closure and has no late answer',await o.p.getByText('HELD_SECRET_MUST_NOT_APPEAR',{exact:true}).count()===0);await o.ctx.close();});
